(()=>{const header=document.querySelector('.site-header');const resize=()=>document.documentElement.style.setProperty('--header-height',header.getBoundingClientRect().height+'px');new ResizeObserver(resize).observe(header);resize();
const region=document.querySelector('#story-detail');let current='';let saved='us1';try{saved=sessionStorage.getItem('case-v3-story')||saved}catch{}
const allowed=/^us[1-5]$/;if(!allowed.test(saved))saved='us1';
for(const a of document.querySelectorAll('a[href$="stories/index.html"]'))a.href=a.getAttribute('href')+'#'+saved;
if(region){const links=[...document.querySelectorAll('[data-story]')],select=document.querySelector('#story-select'),jumps=document.querySelector('.story-jumps');const show=()=>{const match=location.hash.match(/^#(us[1-5])(?:-|$)/);const id=match?match[1]:saved;if(id!==current){region.innerHTML=window.storyContent[id];current=id;try{sessionStorage.setItem('case-v3-story',id)}catch{}links.forEach(a=>{a.href='#'+a.dataset.story;a.classList.toggle('selected',a.dataset.story===id);if(a.dataset.story===id)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')});select.value=id;jumps.innerHTML=[['summary','Summary'],['criteria','Criteria'],['references','References'],['decisions','Decisions'],['states','States'],['traceability','Traceability']].map(([key,label])=>`<a href="#${id}-${key}">${label}</a>`).join('');}const target=location.hash.slice(1);if(target&&target!==id)requestAnimationFrame(()=>document.getElementById(target)?.scrollIntoView());};const switchTo=id=>{history.pushState(null,'','#'+id);show();document.querySelector('.story-tools').scrollIntoView({block:'start'});};links.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();switchTo(a.dataset.story)}));select.addEventListener('change',()=>switchTo(select.value));window.addEventListener('popstate',show);window.addEventListener('hashchange',show);show();}
const modules=[...document.querySelectorAll('.delivery-module')],tabs=[...document.querySelectorAll('[data-module]')];if(modules.length){const show=()=>{const id=modules.some(x=>'#'+x.id===location.hash)?location.hash.slice(1):'sequencing';modules.forEach(x=>x.hidden=x.id!==id);tabs.forEach(a=>{a.classList.toggle('selected',a.dataset.module===id);if(a.dataset.module===id)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')})};tabs.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();history.pushState(null,'',a.getAttribute('href'));show();document.querySelector('.module-selectors').scrollIntoView({block:'start'})}));window.addEventListener('popstate',show);show();}
})();
